            { title: "Ɗabi'un wuƙa da ƙuna", bullets: ["Ku lanƙwasa hannu mai jagora; kada ku kama wuƙa da ke faɗuwa", "Ku ce \"knife\", \"hot\", \"behind\" yayin da kuke motsi", "Busassun tawul ko safar hannu; hannayen tukunya zuwa ciki"] },
            { title: "Ƙasa da ɗaukar kaya", bullets: ["Takalma rufaffu masu hana zamewa", "Ku share abin da ya zube yanzu ko ku sa alama", "Ku lanƙwasa gwiwoyi; ku nemi taimako da kaya masu nauyi"] },
            { title: "Dokokin matasa (na tarayya)", bullets: ["14-15: ba gasa, wuta a buɗe, yawancin tukwanen soya, injunan yanka ko kaɗa na lantarki", "16-17: ba injunan yanka nama, niƙa ko kaɗa abinci na kasuwanci", "Jiharku za ta iya fi tsauri"] }
